    h.setAttribute("role", "button");
    h.setAttribute("tabindex", "0");
    h.setAttribute("aria-label", st.page ? TEXT.labelPage : st.variant === "mediaerr" ? TEXT.labelMedia : st.variant === "frameerr" ? TEXT.labelFrame : TEXT.label);
